	) {

	//Collect the original elements before modifying anything
	// (iterating the element lists while mutating them would be asking for trouble):
	std::vector< VertexRef > original_vertices;
	for (VertexRef v = vertices.begin(); v != vertices.end(); ++v) original_vertices.push_back(v);

	std::vector< EdgeRef > original_edges;
	for (EdgeRef e = edges.begin(); e != edges.end(); ++e) original_edges.push_back(e);

	std::vector< FaceRef > original_faces;
	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (!f->boundary) original_faces.push_back(f);
	}

	//Bisect every original edge, remembering the vertex added on each edge.
	// This does not divide any faces, so every non-boundary n-gon becomes a
	// 2n-gon alternating original vertices (v_i) and edge-center vertices (m_i),
	// and boundary faces simply absorb the extra halfedges.
	std::unordered_map< EdgeCRef, VertexRef > edge_vertex;
	std::unordered_set< VertexCRef > edge_vertices;
	for (EdgeRef e : original_edges) {
		std::optional< VertexRef > v = bisect_edge(e);
		if (!v) continue; //should not happen on a valid mesh
		edge_vertex.emplace(e, *v);
		edge_vertices.insert(*v);
	}

	//For every original non-boundary face, insert a center vertex and
	// split the (now 2n-gon) face into n quads (v_i, m_i, center, m_{i-1}):
	std::unordered_map< FaceCRef, VertexRef > face_vertex;
	for (FaceRef f : original_faces) {
		//collect the halfedges of f leaving original vertices, in ccw order:
		// (A[i]: v_i -> m_i)
		std::vector< HalfedgeRef > A;
		{
			HalfedgeRef h = f->halfedge;
			do {
				if (!edge_vertices.count(h->vertex)) A.push_back(h);
				h = h->next;
			} while (h != f->halfedge);
		}
		uint32_t n = static_cast<uint32_t>(A.size());
		if (n < 3) continue; //not a valid face; leave it alone

		//grab everything the rewiring below will need *before* changing any pointers:
		std::vector< HalfedgeCRef > face_halfedges; //for data interpolation
		std::vector< VertexCRef > face_corners; //for data interpolation
		std::vector< HalfedgeRef > D(n); //D[i]: m_{i-1} -> v_i
		std::vector< VertexRef > M(n); //M[i]: the edge-center vertex m_i
		{
			HalfedgeRef h = f->halfedge;
			do {
				face_halfedges.push_back(h);
				h = h->next;
			} while (h != f->halfedge);
		}
		for (uint32_t i = 0; i < n; ++i) {
			face_corners.push_back(A[i]->vertex);
			M[i] = A[i]->next->vertex;
			D[i] = A[(i + n - 1) % n]->next;
		}

		//make the center vertex:
		VertexRef center = emplace_vertex();
		face_vertex.emplace(f, center);
		interpolate_data(face_corners, center);

		//make the new "spoke" halfedges:
		// B[i]: m_i -> center, C[i]: center -> m_{i-1} (B[i] and C[i+1] are twins, on spoke edge S[i])
		std::vector< HalfedgeRef > B(n), C(n);
		std::vector< EdgeRef > S(n);
		for (uint32_t i = 0; i < n; ++i) {
			B[i] = emplace_halfedge();
			C[i] = emplace_halfedge();
			S[i] = emplace_edge();
			S[i]->halfedge = B[i];
			interpolate_data(face_halfedges, B[i]);
			interpolate_data(face_halfedges, C[i]);
		}

		//rewire into quads; quad i is (v_i, m_i, center, m_{i-1}), ccw:
		// A[i] -> B[i] -> C[i] -> D[i] -> (back to A[i])
		for (uint32_t i = 0; i < n; ++i) {
			FaceRef q = (i == 0) ? f : emplace_face(false);
			q->halfedge = A[i];

			A[i]->next = B[i];
			A[i]->face = q;
			B[i]->set_tnvef(C[(i + 1) % n], C[i], M[i], S[i], q);
			C[i]->set_tnvef(B[(i + n - 1) % n], D[i], center, S[(i + n - 1) % n], q);
			D[i]->face = q; //D[i]->next already points at A[i]
		}
		center->halfedge = C[0];
	}

	//finally, assign positions from the parameter maps:
	for (VertexRef v : original_vertices) {
		if (auto p = vertex_positions.find(v); p != vertex_positions.end()) {
			v->position = p->second;
		}
	}
	for (auto const &[e, v] : edge_vertex) {
		if (auto p = edge_vertex_positions.find(e); p != edge_vertex_positions.end()) {
			v->position = p->second;
		}
	}
	for (auto const &[f, v] : face_vertex) {
		if (auto p = face_vertex_positions.find(f); p != face_vertex_positions.end()) {
			v->position = p->second;
		}
	}
}

void Halfedge_Mesh::flip_orientation() {
	//remember each halfedge's current vertex so that updates don't
	// interfere with each other:
	std::unordered_map< HalfedgeRef, VertexRef > old_vertex;
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		old_vertex.emplace(h, h->vertex);
	}

	//reverse every face cycle; each halfedge keeps its edge, face, and twin,
	// but traverses its edge in the opposite direction:
	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		//collect the cycle while the next pointers are still the old ones:
		std::vector< HalfedgeRef > cycle;
		HalfedgeRef h = f->halfedge;
		do {
			cycle.push_back(h);
			h = h->next;
		} while (h != f->halfedge);
		//each halfedge now follows its predecessor and leaves from
		// the vertex its twin used to leave from:
		for (size_t i = 0; i < cycle.size(); ++i) {
			cycle[i]->next = cycle[(i + cycle.size() - 1) % cycle.size()];
			cycle[i]->vertex = old_vertex[cycle[i]->twin];
		}
	}

	//make each vertex->halfedge point at a halfedge that (now) leaves the vertex:
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		h->vertex->halfedge = h;
	}
}
